nonisolated(unsafe) let unsafeManager = manager
let result = try await runDetached(timeout: inferenceTimeout) {
    // Each diarize() call processes one complete, independent recording.
    // DiarizerManager's SpeakerManager accumulates speaker centroids across
    // calls; without a reset, a recording inherits stale speakers from the
    // previous one and clusters against them (#306 — batch runs showed
    // monotonically increasing speaker IDs across files, 8 clusters where
    // an isolated run of the same audio yields 4).
    unsafeManager.speakerManager.reset()
    return try unsafeManager.performCompleteDiarization(samples, sampleRate: sampleRate)
}

