import Domain
import FluidAudio
import Foundation
@testable import MLInfrastructure
import Testing

// MARK: - Compile-Time Error Translation Matrix

/// Maps every DiarizerError case to its expected domain error.
/// This function is exercised by the exhaustiveness test below.
/// If FluidAudio adds a new DiarizerError case the switch becomes
/// non-exhaustive and this file fails to compile — surfacing the gap
/// before FluidDiarizationPlugin's mapping is updated.
///
/// Expected mapping:
///   .notInitialized       → TranscriptionError.modelNotLoaded
///   .modelDownloadFailed  → TranscriptionError.modelNotLoaded
///   .modelCompilationFailed → TranscriptionError.modelNotLoaded
///   .embeddingExtractionFailed → TranscriptionError.inferenceFailed
///   .invalidAudioData     → TranscriptionError.inferenceFailed
///   .processingFailed     → TranscriptionError.inferenceFailed
///   .memoryAllocationFailed → TranscriptionError.inferenceFailed
///   .invalidArrayBounds   → TranscriptionError.inferenceFailed
private func _diarizerErrorTranslationMatrix(_ error: DiarizerError) -> TranscriptionError {
    switch error {
    case .notInitialized: .modelNotLoaded(underlying: error)
    case .modelDownloadFailed: .modelNotLoaded(underlying: error)
    case .modelCompilationFailed: .modelNotLoaded(underlying: error)
    case .embeddingExtractionFailed: .inferenceFailed(underlying: error)
    case .invalidAudioData: .inferenceFailed(underlying: error)
    case .processingFailed: .inferenceFailed(underlying: error)
    case .memoryAllocationFailed: .inferenceFailed(underlying: error)
    case .invalidArrayBounds: .inferenceFailed(underlying: error)
    }
}

// MARK: - FluidDiarizationPlugin Unit Tests

extension NativeLibraryTests {
    // These tests exercise validation logic and protocol conformance without
    // loading real FluidAudio diarization models. Tests requiring actual ML
    // inference (model download, full diarization pipeline) belong in
    // Tests/Integration.

    @Suite("FluidDiarizationPlugin", .serialized)
    struct FluidDiarizationPluginTests {
        // MARK: - Protocol Conformance

        @Test
        func `FluidDiarizationPlugin conforms to DiarizationEngine at compile time`() {
            // Assigning to an existential verifies compile-time protocol conformance.
            // Fails to compile if FluidDiarizationPlugin is missing any required method.
            let _: any DiarizationEngine = FluidDiarizationPlugin()
        }

        @Test
        func `FluidDiarizationPlugin is usable across concurrency domains via actor Sendable`() async {
            let plugin = FluidDiarizationPlugin()
            // Task.detached crosses a concurrency boundary; only legal if the
            // captured value satisfies Sendable. Actors satisfy Sendable automatically.
            let ready = await Task.detached { await plugin.isReady() }.value
            #expect(ready == false)
        }

        // MARK: - Lifecycle: isReady

        @Test
        func `isReady returns false before prepare is called`() async {
            let plugin = FluidDiarizationPlugin()
            let ready = await plugin.isReady()
            #expect(ready == false)
        }

        // MARK: - Input Validation: empty samples

        @Test
        func `empty samples throw audioTooShort before engine-ready guard`() async {
            // Even without a prepared engine, empty samples must throw .audioTooShort
            // not .modelNotLoaded. Sample-length validation must execute first.
            let plugin = FluidDiarizationPlugin()

            var threwAudioTooShort = false
            var threwModelNotLoaded = false
            do {
                _ = try await plugin.diarize(samples: [], sampleRate: 16000)
            } catch TranscriptionError.audioTooShort {
                threwAudioTooShort = true
            } catch TranscriptionError.modelNotLoaded {
                threwModelNotLoaded = true
            } catch {}

            #expect(threwAudioTooShort == true, "Expected .audioTooShort for empty samples")
            #expect(threwModelNotLoaded == false, "Must not reach engine-ready guard for empty samples")
        }

        // MARK: - Input Validation: engine not ready

        @Test
        func `diarize with valid samples but no prepare throws modelNotLoaded`() async {
            let plugin = FluidDiarizationPlugin()
            // 1 600 samples = 0.1 s at 16 kHz — above any reasonable minimum threshold
            let samples = [Float](repeating: 0.01, count: 1600)

            var threwModelNotLoaded = false
            do {
                _ = try await plugin.diarize(samples: samples, sampleRate: 16000)
            } catch TranscriptionError.modelNotLoaded {
                threwModelNotLoaded = true
            } catch {}

            #expect(threwModelNotLoaded == true, "Expected .modelNotLoaded before prepare() is called")
        }

        // MARK: - DPS-5: Timeout Compliance

        @Test
        func `prepare wraps DiarizerModels download in withTimeout (DPS-5)`() throws {
            let testFile = URL(fileURLWithPath: #filePath)
            let packageRoot = testFile
                .deletingLastPathComponent()
                .deletingLastPathComponent()
                .deletingLastPathComponent()
                .deletingLastPathComponent()
            let sourceFile = packageRoot.appendingPathComponent(
                "Record-ML/Sources/MLInfrastructure/Diarization/FluidDiarizationPlugin.swift"
            )
            let source = try String(contentsOf: sourceFile, encoding: .utf8)
            #expect(
                source.contains("withTimeout"),
                "FluidDiarizationPlugin.prepare must wrap DiarizerModels.downloadIfNeeded() in withTimeout (DPS-5)"
            )
        }

        // MARK: - Concurrent call serialization (F6)

        @Test
        func `concurrent diarize calls are serialized — second call throws inferenceFailed`() async throws {
            let (signalStream, signalContinuation) = AsyncStream<Void>.makeStream()
            let plugin = FluidDiarizationPlugin(
                inferenceTimeout: .seconds(5),
                testInference: { _, _ in
                    signalContinuation.yield()
                    try await Task.sleep(for: .milliseconds(200))
                    return []
                }
            )

            let samples = [Float](repeating: 0.01, count: 1600)

            // Start first call — runs the slow test inference function
            async let firstResult: [SpeakerSegment] = try plugin.diarize(samples: samples, sampleRate: 16000)

            // Wait for the signal that inference started (deterministic, no sleep)
            for await _ in signalStream { break }

            // Second concurrent call must throw .inferenceFailed (in-flight guard)
            var secondThrewInferenceFailed = false
            do {
                _ = try await plugin.diarize(samples: samples, sampleRate: 16000)
            } catch TranscriptionError.inferenceFailed {
                secondThrewInferenceFailed = true
            } catch {}

            #expect(secondThrewInferenceFailed, "Second concurrent diarize() must throw .inferenceFailed")

            // First call should complete cleanly
            _ = try await firstResult
        }

        // MARK: - Tuning → DiarizerConfig mapping (issue #306)

        @Test
        func `default tuning maps to FluidAudio DiarizerConfig defaults`() {
            let config = makeDiarizerConfig(from: DiarizationTuning())
            let defaults = DiarizerConfig.default
            #expect(config.clusteringThreshold == defaults.clusteringThreshold)
            #expect(config.minEmbeddingUpdateDuration == defaults.minEmbeddingUpdateDuration)
            #expect(config.numClusters == defaults.numClusters)
            #expect(config.minSpeechDuration == defaults.minSpeechDuration)
            #expect(config.minSilenceGap == defaults.minSilenceGap)
        }

        @Test
        func `non-nil tuning overrides are reflected in the DiarizerConfig`() {
            let tuning = DiarizationTuning(
                clusteringThreshold: 0.55,
                minEmbeddingUpdateDuration: 3.5,
                numClusters: 4
            )
            let config = makeDiarizerConfig(from: tuning)
            #expect(config.clusteringThreshold == 0.55)
            #expect(config.minEmbeddingUpdateDuration == 3.5)
            #expect(config.numClusters == 4)
            // Unset fields must retain FluidAudio defaults.
            #expect(config.minSpeechDuration == DiarizerConfig.default.minSpeechDuration)
        }

        @Test
        func `partial tuning overrides only the specified field`() {
            let tuning = DiarizationTuning(clusteringThreshold: 0.6)
            let config = makeDiarizerConfig(from: tuning)
            #expect(config.clusteringThreshold == 0.6)
            #expect(config.minEmbeddingUpdateDuration == DiarizerConfig.default.minEmbeddingUpdateDuration)
            #expect(config.numClusters == DiarizerConfig.default.numClusters)
        }

        // MARK: - Error Translation Matrix

        @Test
        func `DiarizerError mapping is exhaustive (compile-time guard)`() {
            // Calling _diarizerErrorTranslationMatrix forces the compiler to evaluate
            // the exhaustive switch over DiarizerError. If FluidAudio adds a new case,
            // this file fails to compile until FluidDiarizationPlugin's mapping is updated.
            let error = DiarizerError.processingFailed("test")
            let domainError = _diarizerErrorTranslationMatrix(error)
            if case .inferenceFailed = domainError {
                // processingFailed correctly maps to inferenceFailed
            } else {
                Issue.record("processingFailed must map to .inferenceFailed")
            }
        }
    }
} // extension NativeLibraryTests

