// MARK: Reference overlap

/// Total reference time (seconds) during which two or more speakers talk
/// simultaneously. This time is structurally unreachable for any
/// single-label diarization output — it bounds how far exclusive-segment
/// pipelines can ever get on this recording (#308 item 1).
static func referenceOverlapSeconds(reference: [RTTMTurn]) -> Double {
    // Sweep line over turn boundaries counting active speakers.
    var events: [(time: Double, delta: Int)] = []
    for turn in reference {
        events.append((turn.start, 1))
        events.append((turn.end, -1))
    }
    events.sort { $0.time < $1.time }
    var active = 0
    var overlap = 0.0
    var prev = 0.0
    for event in events {
        if active >= 2 { overlap += event.time - prev }
        active += event.delta
        prev = event.time
    }
    return overlap
}

