                    let agreement = coAssociationAgreement(labelings[a], labelings[b])
                    pairAgreement[a][b] = agreement
                    pairAgreement[b][a] = agreement
                }
            }
            for a in 0..<restarts {
                let others = (0..<restarts).filter { $0 != a }.map { pairAgreement[a][$0] }
                outcomes[a].consensus = others.reduce(0, +) / Double(others.count)
            }
