func cosine(_ a: [Double], _ b: [Double]) -> Double {
    var dot = 0.0
    var na = 0.0
    var nb = 0.0
    for i in 0..<min(a.count, b.count) {
        dot += a[i] * b[i]
        na += a[i] * a[i]
        nb += b[i] * b[i]
    }
    let denominator = sqrt(na) * sqrt(nb)
    return denominator > 0 ? dot / denominator : 0
}

