                    endTime: seg.endTime,
                    confidence: seg.confidence
                )
            }
            for (from, to) in merges.sorted(by: { $0.key < $1.key }) {
                progress("pass 2 merge: \(from) → \(to)")
            }
        }
    }

    return Result(
        segments: segments, runs: outcomes, medoidIndex: medoid.index, merges: merges
    )
}

toolUseResult.newString:
    // Pass 2: centroid-based cluster merging on the medoid run.
    var segments = medoid.segments
    var merges: [String: String] = [:]
    if let mergeThreshold {
        merges = centroidMerges(
            chunks: allChunkEmbeddings[medoid.index], threshold: mergeThreshold
        )
        segments = applyMerges(merges, to: segments)
        for (from, to) in merges.sorted(by: { $0.key < $1.key }) {
            progress("pass 2 merge: \(from) → \(to)")
        }
    }

    return Result(
        segments: segments, runs: outcomes, medoidIndex: medoid.index, merges: merges
    )
}

/// Relabel segments whose cluster was merged away by pass 2.
private static func applyMerges(
    _ merges: [String: String], to segments: [SpeakerSegment]
) -> [SpeakerSegment] {
    guard !merges.isEmpty else { return segments }
    return segments.map { seg in
        guard let target = merges[seg.speakerId.rawValue] else { return seg }
        return SpeakerSegment(
            speakerId: SpeakerID(target),
            startTime: seg.startTime,
            endTime: seg.endTime,
            confidence: seg.confidence
        )
    }
}
